const {chromium}=require('playwright');
const fs=require('fs');const path=require('path');const {pathToFileURL}=require('url');
(async()=>{const dir=path.join(__dirname,'Software','Biblioteca_Glasses');const b=await chromium.launch({headless:true,channel:'msedge'});const page=await b.newPage({viewport:{width:1440,height:1000}});await page.goto(pathToFileURL(path.join(dir,'INDEX.html')).href);const all=await page.locator('[data-resource]').count();await page.locator('#filter').fill('BtGlassRecorder');await page.locator('#filter').fill('Android');const visible=await page.locator('[data-resource]:visible').count();if(!visible||visible>=all)throw Error('Search filter failed');await page.locator('#filter').fill('');const links=await page.locator('a').evaluateAll(a=>a.map(x=>x.getAttribute('href')));const missing=links.filter(x=>x&&!/^(https?:|#)/.test(x)).filter(x=>!fs.existsSync(path.resolve(dir,decodeURIComponent(x))));if(missing.length)throw Error(JSON.stringify(missing));await page.screenshot({path:path.join(dir,'preview.png'),fullPage:false});await page.setViewportSize({width:390,height:844});const overflow=await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth);if(overflow)throw Error('Mobile overflow');fs.writeFileSync(path.join(dir,'browser-validation.json'),JSON.stringify({all,androidResults:visible,missing,mobileOverflow:overflow},null,2));console.log(JSON.stringify({all,androidResults:visible,missing,mobileOverflow:overflow}));await b.close()})().catch(e=>{console.error(e);process.exit(1)});
